 const lifecycle=()=>{if(!active())pause()},blur=()=>pause(),language=()=>{buildBackground();updateHierarchy();if(selected)inspect(g.exhibits.find(e=>e.id===selected));else introduction();draw()};
 document.addEventListener('fullscreenchange',syncFullscreen);document.addEventListener('keydown',down);document.addEventListener('keyup',up);document.addEventListener('portfolio-windows-changed',lifecycle);document.addEventListener('visibilitychange',lifecycle);document.addEventListener('portfolio-preferences',language);window.addEventListener('blur',blur);owner?.addEventListener('window-closing',pause);
