 return ()=>{disposed=true;stop();if(document.fullscreenElement===host)void document.exitFullscreen().catch(()=>{});owner?.classList.remove('museum-expanded');document.removeEventListener('fullscreenchange',syncFullscreen);resize.disconnect();document.removeEventListener('keydown',down);document.removeEventListener('keyup',up);document.removeEventListener('portfolio-windows-changed',lifecycle);document.removeEventListener('visibilitychange',lifecycle);document.removeEventListener('portfolio-preferences',language);window.removeEventListener('blur',blur);owner?.removeEventListener('window-closing',pause);for(const img of images.values()){img.onload=null;img.onerror=null}images.clear();host.replaceChildren()};
