function drawPlayer(c,g){const x=Math.round(g.player.x*TILE),y=Math.round(g.player.y*TILE),leg=Math.floor(g.distance*3)%2;c.fillStyle='#3c413e50';c.fillRect(x-5,y+2,12,4);c.fillStyle='#333c43';c.fillRect(x-4,y-3,4,7+leg);c.fillRect(x+2,y-3,4,8-leg);c.fillStyle='#253238';c.fillRect(x-5,y+4+leg,5,2);c.fillRect(x+2,y+5-leg,5,2);c.fillStyle='#487c85';c.fillRect(x-5,y-11,11,10);c.fillStyle='#75a0a3';c.fillRect(x-4,y-11,8,2);c.fillStyle='#e4ae83';c.fillRect(x-7,y-9,3,6);c.fillRect(x+6,y-9,3,6);c.fillRect(x-4,y-18,10,8);c.fillStyle='#403a36';c.fillRect(x-5,y-21,11,5);c.fillRect(x-5,y-18,3,4);c.fillRect(x+5,y-18,2,3);c.fillStyle='#373634';c.fillRect(x+(g.facing>0?3:-2),y-16,1,2);c.fillStyle='#c77a50';c.fillRect(x+(g.facing>0?-4:3),y-9,4,7)}

